"""S3 - Quality evaluation of an output generated by another model (HelpSteer2).

Each item is a (prompt, response) pair where the response was generated by an LLM and rated by
human annotators on a 0-4 Likert scale. We use the *helpfulness* attribute, whose level descriptions
below follow the HelpSteer2 annotation guidelines (Wang et al. 2024). The task is ordinal: Jev
answers with its `Score` primitive (a probability for each level), the LLM with an integer level.
"""

from __future__ import annotations

import gzip
import json
from collections import Counter

from jev_benchmark.config import RAW_DIR
from jev_benchmark.tasks.base import (
    Example,
    Task,
    TaskKind,
    balanced_quotas,
    download,
    stratified_sample,
)

HELPSTEER2_VAL_URL = "https://huggingface.co/datasets/nvidia/HelpSteer2/resolve/main/validation.jsonl.gz"

LEVELS: dict[str, str] = {
    "0": "Not helpful at all: the response is not useful or helpful at all and completely misses "
    "the essence of what the user wanted.",
    "1": "Borderline unhelpful: the response mostly does not capture what the user was looking "
    "for, but it is still usable and helpful in a small way.",
    "2": "Partially helpful: the response is partially helpful but misses the overall goal of the "
    "user's query in some way; it does not fully satisfy what the user was looking for.",
    "3": "Mostly helpful: the response is mostly helpful and mainly aligned with what the user was "
    "looking for, but there is still some room for improvement.",
    "4": "Perfectly helpful: the response is extremely helpful and completely aligned with the "
    "spirit of what the prompt was asking for.",
}

TASK = Task(
    name="output_quality",
    title="S3 - Valutazione della qualita' di un output generato",
    kind=TaskKind.ORDINAL,
    instructions=(
        "Rate the overall helpfulness of the assistant response to the user prompt. If the prompt "
        "contains an earlier conversation, judge the response to the last user turn in that context. "
        "Helpfulness depends on correctness, completeness, coherence and an appropriate level of detail."
    ),
    labels=LEVELS,
    dataset="HelpSteer2 (NVIDIA, Wang et al. 2024), split validation, CC BY 4.0",
)

PASS_THRESHOLD = 3  # quality gate: a response "passes" when helpfulness >= 3


def render_prompt(prompt: str) -> str:
    """Turn HelpSteer2 multi-turn markup into a readable transcript."""
    if "<extra_id_1>" not in prompt:
        return prompt
    text = prompt.replace("\n<extra_id_1>Assistant\n", "\n\nAssistant: ")
    text = text.replace("\n<extra_id_1>User\n", "\n\nUser: ")
    return f"User: {text}"


def prepare(total: int = 500, seed: int = 42) -> list[Example]:
    """`total` validation pairs, as balanced across the 5 levels as the split allows.

    The validation split has only 78 pairs at level 0 and 93 at level 1, so those are all taken and
    the other levels get ~110 each (v1 used 60 per level: those 300 are all included).
    """
    path = download(HELPSTEER2_VAL_URL, RAW_DIR / "helpsteer2" / "validation.jsonl.gz")
    with gzip.open(path, "rt", encoding="utf-8") as fh:
        rows = [(i, json.loads(line)) for i, line in enumerate(fh)]
    level = lambda r: str(r[1]["helpfulness"])  # noqa: E731
    quotas = balanced_quotas(Counter(level(r) for r in rows), total, seed)
    sampled = stratified_sample(rows, key=level, per_class=quotas, seed=seed)
    return [
        Example(
            id=f"helpsteer2-val-{i:04d}",
            label=str(row["helpfulness"]),
            state={"prompt": render_prompt(row["prompt"]), "response": row["response"]},
            meta={
                "split": "validation",
                "row": i,
                **{k: row[k] for k in ("correctness", "coherence", "complexity", "verbosity")},
            },
        )
        for i, row in sampled
    ]
